"""Download the vendored test corpora and record what was downloaded.

This is the only thing in the repository that reaches the network, and it only
runs when somebody asks it to. Everything it writes is committed, so a test run
never has to fetch anything and a run from six months ago can be reproduced
exactly.

    python tools/vendor/fetch.py --update            refresh every source
    python tools/vendor/fetch.py --update whatwg-url refresh one of them

Refreshing rewrites tests/data/LOCK.toml with the new digests. Review that diff
the same way you would review a dependency bump, because that is what it is: the
assertions the test suite makes are about to change based on a file somebody else
controls.
"""

from __future__ import annotations

import argparse
import hashlib
import sys
import tomllib
import urllib.request
from datetime import date
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCES = ROOT / "tools" / "vendor" / "sources.toml"
LOCK = ROOT / "tests" / "data" / "LOCK.toml"

# Long enough that a slow mirror still finishes, short enough that a hung
# connection does not leave somebody staring at a silent terminal.
TIMEOUT_SECONDS = 120


def load_sources() -> list[dict[str, str]]:
    with SOURCES.open("rb") as handle:
        return tomllib.load(handle)["source"]


def load_lock() -> dict[str, dict[str, object]]:
    if not LOCK.exists():
        return {}
    with LOCK.open("rb") as handle:
        return tomllib.load(handle).get("file", {})


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def fetch(url: str) -> bytes:
    request = urllib.request.Request(
        url, headers={"User-Agent": "mojo.httpx vendor fetch"}
    )
    with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as response:
        return response.read()


def write_lock(entries: dict[str, dict[str, object]]) -> None:
    lines = [
        "# Generated by tools/vendor/fetch.py. Do not edit by hand.",
        "#",
        "# Each entry pins one vendored corpus to the exact bytes that were",
        "# downloaded. `pixi run vendor-check` compares what is on disk against",
        "# this, so a file that changed without a fetch shows up as a failure",
        "# rather than as a test that quietly started asserting something else.",
        "",
    ]
    for name in sorted(entries):
        entry = entries[name]
        lines.append(f"[file.{name}]")
        lines.append(f'path = "{entry["path"]}"')
        lines.append(f'url = "{entry["url"]}"')
        lines.append(f'sha256 = "{entry["sha256"]}"')
        lines.append(f"size = {entry['size']}")
        lines.append(f'retrieved = "{entry["retrieved"]}"')
        lines.append("")
    LOCK.parent.mkdir(parents=True, exist_ok=True)
    LOCK.write_text("\n".join(lines))


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--update",
        action="store_true",
        help="actually download. Without it this only reports what would change.",
    )
    parser.add_argument("names", nargs="*", help="sources to fetch, default all")
    args = parser.parse_args()

    sources = load_sources()
    if args.names:
        known = {source["name"] for source in sources}
        unknown = [name for name in args.names if name not in known]
        if unknown:
            # A typo here would silently fetch nothing and report success, which
            # is the one outcome that must not happen in a tool whose job is to
            # say what the tests are running against.
            print(f"no source called {', '.join(unknown)}", file=sys.stderr)
            return 2
        sources = [source for source in sources if source["name"] in args.names]

    entries = load_lock()
    changed = False
    for source in sources:
        name = source["name"]
        path = ROOT / source["path"]
        if not args.update:
            state = "present" if path.exists() else "missing"
            print(f"{name}: {state}, would fetch {source['url']}")
            continue
        print(f"{name}: fetching {source['url']}")
        data = fetch(source["url"])
        previous = entries.get(name, {}).get("sha256")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
        entries[name] = {
            "path": source["path"],
            "url": source["url"],
            "sha256": digest(data),
            "size": len(data),
            "retrieved": date.today().isoformat(),
        }
        if previous != entries[name]["sha256"]:
            changed = True
            print(f"{name}: content changed, {len(data)} bytes")
        else:
            print(f"{name}: unchanged, {len(data)} bytes")

    if args.update:
        write_lock(entries)
        if changed:
            print("\nLOCK.toml updated. Review the corpus diff before committing.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
